def generar_configuracion_maestra():
    logging.info("Iniciando generacion de configuracion para esquema SPE.")
    
    nombres_tablas = []
    try:
        with open('tablas.txt', 'r', encoding='utf-8') as f:
            for l in f:
                clean_line = l.strip()
                if not clean_line or clean_line.startswith('---') or clean_line.upper().startswith('TABLE_NAME'):
                    continue
                
                nombre = clean_line.split('|')[0].strip()
                if nombre:
                    nombres_tablas.append(nombre)
        
        logging.info(f"Lectura exitosa: {len(nombres_tablas)} tablas identificadas.")
        
    except FileNotFoundError:
        logging.error("Archivo tablas.txt no encontrado.")
        return

    # 3. CONSTRUCCION DE LA ESTRUCTURA YAML (Esquema + Tablas)
    # Se define el esquema en la raiz del documento
    config_maestra = {
        'esquema_origen': "SPE",
        'tablas': {}
    }
    
    conteo_sensibles = 0

    for tabla in nombres_tablas:
        destino = "POSTGRESQL" if tabla in tablas_con_relaciones else "MONGODB"
        es_sensible = tabla in tablas_sensibles
        
        if es_sensible:
            conteo_sensibles += 1
        
        config_maestra['tablas'][tabla] = {
            'descripcion': f"Inventario tecnico de la tabla {tabla}",
            'destino_sugerido': destino,
            'sensible': es_sensible
        }

    # 4. ESCRITURA FISICA DEL ARCHIVO
    os.makedirs('config', exist_ok=True)
    try:
        with open('config/tablas.yaml', 'w', encoding='utf-8') as f:
            # allow_unicode=True para mantener tildes si las hubiera
            # sort_keys=False para mantener el esquema al principio
            yaml.dump(config_maestra, f, sort_keys=False, allow_unicode=True)
        
        logging.info("Archivo config/tablas.yaml generado correctamente con campo esquema.")
        logging.info(f"Resumen final: {len(nombres_tablas)} tablas totales, {conteo_sensibles} sensibles.")
        
    except Exception as e:
        logging.error(f"Error en la escritura del archivo: {str(e)}")

if __name__ == "__main__":
    generar_configuracion_maestra()